//! Builds a .ppt from scratch: every record generated by `office_ppt::write`,
//! except the MainMaster and Slide shape trees, which are carried over as blobs
//! so that the document-level bookkeeping can be tested on its own.
use office_ppt::write;

fn records(data: &[u8]) -> Vec<(u16, usize, usize)> {
    let mut out = Vec::new();
    let mut at = 0usize;
    while at + 8 <= data.len() {
        let kind = u16::from_le_bytes([data[at + 2], data[at + 3]]);
        let len = u32::from_le_bytes([data[at + 4], data[at + 5], data[at + 6], data[at + 7]]) as usize;
        if at + 8 + len > data.len() {
            break;
        }
        out.push((kind, at, at + 8 + len));
        at += 8 + len;
    }
    out
}

fn main() {
    let template = std::fs::read("samples/void-ms.ppt").expect("template");
    let cfb = office_cfb::Cfb::parse(template).expect("cfb");
    let stream = cfb.stream("PowerPoint Document").expect("stream").to_vec();
    let kids = records(&stream);
    let payload = |kind: u16| -> Vec<u8> {
        let (_, start, end) = *kids.iter().find(|(k, _, _)| *k == kind).expect("record");
        stream[start + 8..end].to_vec()
    };
    let blob = |kind: u16| -> Vec<u8> {
        let (_, start, end) = *kids.iter().find(|(k, _, _)| *k == kind).expect("record");
        stream[start..end].to_vec()
    };
    let doc_body = payload(0x03E8);
    let doc_kids = records(&doc_body);
    let doc_payload = |kind: u16| -> Vec<u8> {
        let (_, start, end) = *doc_kids.iter().find(|(k, _, _)| *k == kind).expect("doc child");
        doc_body[start + 8..end].to_vec()
    };
    let doc_atom = doc_payload(0x03E9);
    let theme = doc_payload(0x0428);
    let env = doc_payload(0x03F2);
    let style = {
        let mut at = 0usize;
        let mut found = None;
        while at + 8 <= env.len() {
            let kind = u16::from_le_bytes([env[at + 2], env[at + 3]]);
            let len = u32::from_le_bytes([env[at + 4], env[at + 5], env[at + 6], env[at + 7]]) as usize;
            if kind == 0x0FA3 {
                found = Some(env[at + 8..at + 8 + len].to_vec());
                break;
            }
            at += 8 + len;
        }
        found.expect("style")
    };
    let master = blob(0x03F8);
    let slide = blob(0x03EE);

    let mut out = Vec::new();
    let document = write::document(&[0, 7, 1], &style, &theme, &doc_atom);
    out.extend_from_slice(&document);
    let master_at = out.len();
    out.extend_from_slice(&master);
    let slide_at = out.len();
    out.extend_from_slice(&slide);

    // PersistDirectoryAtom: one cluster with three entries.
    let mut pd = Vec::new();
    pd.extend_from_slice(&(1u32 | (3u32 << 20)).to_le_bytes());
    pd.extend_from_slice(&0u32.to_le_bytes());
    pd.extend_from_slice(&(master_at as u32).to_le_bytes());
    pd.extend_from_slice(&(slide_at as u32).to_le_bytes());
    let pd_at = out.len();
    out.extend_from_slice(&write::ppt_public(0, 0, 0x1772, &pd));

    let mut ue = Vec::new();
    ue.extend_from_slice(&0x0102u32.to_le_bytes());
    ue.extend_from_slice(&0x17DFu16.to_le_bytes());
    ue.extend_from_slice(&[0, 3]);
    ue.extend_from_slice(&0u32.to_le_bytes());
    ue.extend_from_slice(&(pd_at as u32).to_le_bytes());
    ue.extend_from_slice(&1u32.to_le_bytes());
    ue.extend_from_slice(&3u32.to_le_bytes());
    ue.extend_from_slice(&1u16.to_le_bytes());
    ue.extend_from_slice(&0u16.to_le_bytes());
    let ue_at = out.len();
    out.extend_from_slice(&write::ppt_public(0, 0, 0x0FF5, &ue));

    let user = write::current_user(ue_at as u32, "rust");
    let file = office_cfb::write(&[
        office_cfb::OutputStream::new("PowerPoint Document", &out),
        office_cfb::OutputStream::new("Current User", &user),
    ]);
    std::fs::write("samples/scratch3.ppt", &file).expect("write");
    println!("scratch3.ppt {} bytes, doc {} master {} slide {} pd {} ue {}", file.len(), document.len(), master_at, slide_at, pd_at, ue_at);
}
